def match_at(text, pattern, start):
    if start < 0 or start > len(text):
        return None
    if start + len(pattern) > len(text):
        return False
    j = 0
    while j < len(pattern):
        if text[start + j] != pattern[j]:
            return False
        j = j + 1
    return True

