def repeating_unit_length(text):
    n = len(text)
    if n == 0:
        return 0
    table = prefix_table(text)
    border = table[n - 1]
    while border > 0:
        size = n - border
        if n % size == 0:
            return size
        border = table[border - 1]
    return n

